import{_ as t,o as a,c as r,a0 as n}from"./chunks/framework.BQGW-Zpy.js";const g=JSON.parse('{"title":"Go-to-Market Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"business/go-to-market.md","filePath":"business/go-to-market.md"}'),i={name:"business/go-to-market.md"};function o(s,e,d,h,c,l){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="go-to-market-strategy" tabindex="-1">Go-to-Market Strategy <a class="header-anchor" href="#go-to-market-strategy" aria-label="Permalink to &quot;Go-to-Market Strategy&quot;">​</a></h1><h2 id="beachhead-one-corridor-not-a-global-launch" tabindex="-1">Beachhead: one corridor, not a global launch <a class="header-anchor" href="#beachhead-one-corridor-not-a-global-launch" aria-label="Permalink to &quot;Beachhead: one corridor, not a global launch&quot;">​</a></h2><p>The temptation in cross-border payments is to claim broad country coverage from day one. The defensible version is narrower: <strong>launch in the corridor with the strongest evidence already gathered, prove it works, then expand corridor by corridor.</strong></p><p>Based on the research already done in this project (see <a href="./potential-partners.html">Potential Partners</a> and <a href="./alternative-approaches.html">Alternative Approaches</a>), Year 1 targets the largest freelancer market in each of three priority regions: <strong>Nigeria</strong> (Africa), <strong>India</strong> (Asia), and <strong>Brazil</strong> (Latin America). All three are corridors the systemic alternatives (UPI-PayNow, Project Nexus, ASEAN mesh) do not reach at the retail freelancer level, since they require a domestic instant-payment system on the receiving end that most of these markets don&#39;t yet have linked internationally the way Southeast Asia does.</p><h2 id="launch-sequence" tabindex="-1">Launch sequence <a class="header-anchor" href="#launch-sequence" aria-label="Permalink to &quot;Launch sequence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Focus</th><th>Exit criterion</th></tr></thead><tbody><tr><td>1. Three parallel corridors</td><td>One sending country (EU, via SEPA) to Nigeria, India, and Brazil, one payout partner each</td><td>A real transfer settles in each corridor, payout confirmed, compliance anchor verifiable on HashScan</td></tr><tr><td>2. Corridor depth</td><td>Add 2-3 more receiving corridors per region using the same sending-side rail</td><td>Partner agreements signed, not new engineering</td></tr><tr><td>3. Second sending market</td><td>Add a second sending country/currency (e.g. UK, GBP)</td><td>Proves the model isn&#39;t EUR-specific</td></tr><tr><td>4. Second target segment</td><td>Expand from freelancer remittances to general diaspora remittances (the second target market named in <a href="./../get-started/problem-analysis.html">Problem Analysis</a>)</td><td>Volume from segment 2 exceeds a defined threshold relative to segment 1</td></tr></tbody></table><p>Each phase is gated on <strong>partner agreements</strong>, not engineering work. Consistent with the scalability analysis in <a href="./business-model.html">Business Model</a>: this is a commercially-constrained business, not a technically-constrained one.</p><h2 id="customer-acquisition" tabindex="-1">Customer acquisition <a class="header-anchor" href="#customer-acquisition" aria-label="Permalink to &quot;Customer acquisition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Channel</th><th>Why it fits this specific segment</th></tr></thead><tbody><tr><td>Freelance platform partnerships</td><td>Freelancers already aggregate on platforms; a payout-method integration reaches thousands of users through one partnership, not one user at a time</td></tr><tr><td>Diaspora community channels</td><td>WhatsApp groups, community associations, and remittance comparison sites are where diaspora senders already research options, not general advertising</td></tr><tr><td>Partner co-marketing</td><td>Licensed payout partners (Yellow Card, MTN MoMo, and equivalents in India/Brazil) have existing user bases; a co-marketing agreement reaches recipients&#39; senders indirectly</td></tr></tbody></table><p><strong>What this explicitly avoids:</strong> paid general-audience advertising as a first channel. Cross-border remittance senders are price- and trust-sensitive; acquisition in this space works through existing trusted channels (community, platform, partner), not broad awareness campaigns, especially pre-revenue.</p><h2 id="pricing-at-launch" tabindex="-1">Pricing at launch <a class="header-anchor" href="#pricing-at-launch" aria-label="Permalink to &quot;Pricing at launch&quot;">​</a></h2><p>Per <a href="./business-model.html">Business Model</a>: a transparent flat fee plus a stated FX spread, meaningfully below the global average cost, undercutting the <em>hidden</em> spread most incumbents charge, not necessarily the <em>total</em> cost, since the licensed partners&#39; margins are the majority of the cost regardless of who orchestrates the transfer. The defensible pricing claim at launch is transparency and a real, moderate discount, not being unconditionally cheaper. (The exact discount figure and full unit economics are still being finalized separately.)</p><h2 id="what-would-make-this-fail" tabindex="-1">What would make this fail <a class="header-anchor" href="#what-would-make-this-fail" aria-label="Permalink to &quot;What would make this fail&quot;">​</a></h2><p>Per the same section&#39;s own risk framing: a licensed CASP (Due, BVNK) adding a compliance-anchoring layer of their own would remove this project&#39;s main differentiation quickly, since they already have the licensing and corridor coverage. The go-to-market bet is that they are optimizing for corridors with existing volume, leaving the corridors this project targets under-served for long enough to establish a partner relationship advantage.</p>',14)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
